1. import * as core from "@actions/core";
2. import * as github from "@actions/github";
3. import type * as Webhooks from "@octokit/webhooks-types";
4. 
5. const closesMatcher = /aria-label="This (?:commit|pull request) closes issue #(\d+)\."/g;
6. 
7. const releaseLinkTemplateRegex = /{release_link}/g;
8. const releaseNameTemplateRegex = /{release_name}/g;
9. const releaseTagTemplateRegex = /{release_tag}/g;
10. 
11. (async function main() {
12.   try {
13.     const payload = github.context
14.       .payload as Webhooks.EventPayloadMap["release"];
15. 
16.     const githubToken = core.getInput("GITHUB_TOKEN");
17.     const octokit = github.getOctokit(githubToken);
18. 
19.     const commentTemplate = core.getInput("comment-template");
20.     const labelTemplate = core.getInput("label-template") || null;
21.     const skipLabelTemplate = core.getInput("skip-label") || null;
22. 
23.     // watch out, this is returning deleted releases for some reason
24.     const { data: releases } = await octokit.repos.listReleases({
25.       ...github.context.repo,
26.       per_page: 2,
27.     });
28. 
29.     if (releases.length < 2) {
30.       if (!releases.length) {
31.         core.error("no releases found");
32.         return;
33.       }
34. 
35.       core.info("first release");
36.       return;
37.     }
38. 
39.     const [currentRelease, priorRelease] = releases;
40. 
41.     const {
42.       data: { commits },
43.     } = await octokit.repos.compareCommits({
44.       ...github.context.repo,
45.       base: priorRelease.tag_name,
46.       head: currentRelease.tag_name,
47.     });
48. 
49.     core.info(`${priorRelease.tag_name}...${currentRelease.tag_name}`);
50. 
51.     const releaseLabel = currentRelease.name || currentRelease.tag_name;
52. 
53.     const comment = commentTemplate
54.       .trim()
55.       .replace(
56.         releaseLinkTemplateRegex,
57.         `[${releaseLabel}](${currentRelease.html_url})`
58.       )
59.       .replace(releaseNameTemplateRegex, currentRelease.name)
60.       .replace(releaseTagTemplateRegex, currentRelease.tag_name);
61.     const parseLabels = (rawInput: string | null) =>
62.       rawInput
63.         ?.replace(releaseNameTemplateRegex, currentRelease.name)
64.         ?.replace(releaseTagTemplateRegex, currentRelease.tag_name)
65.         ?.split(",")
66.         ?.map((l) => l.trim())
67.         .filter((l) => l);
68.     const labels = parseLabels(labelTemplate);
69.     const skipLabels = parseLabels(skipLabelTemplate);
70. 
71.     const linkedIssuesPrs = new Set<string>();
72. 
73.     await Promise.all(
74.       commits.map((commit) =>
75.         (async () => {
76.           const query = `
77.             {
78.               resource(url: "${payload.repository.html_url}/commit/${commit.sha}") {
79.                 ... on Commit {
80.                   messageHeadlineHTML
81.                   messageBodyHTML
82.                   associatedPullRequests(first: 10) {
83.                     pageInfo {
84.                       hasNextPage
85.                     }
86.                     edges {
87.                       node {
88.                         bodyHTML
89.                         number
90.                         labels(first: 10) {
91.                           pageInfo {
92.                             hasNextPage
93.                           }
94.                           nodes {
95.                             name
96.                           }
97.                         }
98.                         timelineItems(itemTypes: [CONNECTED_EVENT, DISCONNECTED_EVENT], first: 100) {
99.                           pageInfo {
100.                             hasNextPage
101.                           }
102.                           nodes {
103.                             ... on ConnectedEvent {
104.                               __typename
105.                               isCrossRepository
106.                               subject {
107.                                 ... on Issue {
108.                                   number
109.                                 }
110.                               }
111.                             }
112.                             ... on DisconnectedEvent {
113.                               __typename
114.                               isCrossRepository
115.                               subject {
116.                                 ... on Issue {
117.                                   number
118.                                 }
119.                               }
120.                             }
121.                           }
122.                         }
123.                       }
124.                     }
125.                   }
126.                 }
127.               }
128.             }
129.           `;
130.           const response: {
131.             resource: null | {
132.               messageHeadlineHTML: string;
133.               messageBodyHTML: string;
134.               associatedPullRequests: {
135.                 pageInfo: { hasNextPage: boolean };
136.                 edges: ReadonlyArray<{
137.                   node: {
138.                     bodyHTML: string;
139.                     number: number;
140.                     labels: {
141.                       pageInfo: { hasNextPage: boolean };
142.                       nodes: ReadonlyArray<{
143.                         name: string;
144.                       }>;
145.                     };
146.                     timelineItems: {
147.                       pageInfo: { hasNextPage: boolean };
148.                       nodes: ReadonlyArray<{
149.                         __typename: "ConnectedEvent" | "DisconnectedEvent";
150.                         isCrossRepository: boolean;
151.                         subject: {
152.                           number: number;
153.                         };
154.                       }>;
155.                     };
156.                   };
157.                 }>;
158.               };
159.             };
160.           } = await octokit.graphql(query);
161. 
162.           if (!response.resource) {
163.             return;
164.           }
165. 
166.           core.info(JSON.stringify(response.resource, null, 2));
167. 
168.           const html = [
169.             response.resource.messageHeadlineHTML,
170.             response.resource.messageBodyHTML,
171.             ...response.resource.associatedPullRequests.edges.map(
172.               (pr) => pr.node.bodyHTML
173.             ),
174.           ].join(" ");
175.           for (const match of html.matchAll(closesMatcher)) {
176.             const [, num] = match;
177.             linkedIssuesPrs.add(num);
178.           }
179. 
180.           if (response.resource.associatedPullRequests.pageInfo.hasNextPage) {
181.             core.warning(`Too many PRs associated with ${commit.sha}`);
182.           }
183. 
184.           const seen = new Set<number>();
185.           const associatedPRs = response.resource.associatedPullRequests.edges;
186.           for (const associatedPR of associatedPRs) {
187.             if (associatedPR.node.timelineItems.pageInfo.hasNextPage) {
188.               core.warning(`Too many links for #${associatedPR.node.number}`);
189.             }
190.             if (associatedPR.node.labels.pageInfo.hasNextPage) {
191.               core.warning(`Too many labels for #${associatedPR.node.number}`);
192.             }
193.             // a skip labels is present on this PR
194.             if (
195.               skipLabels?.some((l) =>
196.                 associatedPR.node.labels.nodes.some(({ name }) => name === l)
197.               )
198.             ) {
199.               continue;
200.             }
201.             linkedIssuesPrs.add(`${associatedPR.node.number}`);
202.             // these are sorted by creation date in ascending order. The latest event for a given issue/PR is all we need
203.             // ignore links that aren't part of this repo
204.             const links = associatedPR.node.timelineItems.nodes
205.               .filter((node) => !node.isCrossRepository)
206.               .reverse();
207.             for (const link of links) {
208.               if (seen.has(link.subject.number)) {
209.                 continue;
210.               }
211.               if (link.__typename == "ConnectedEvent") {
212.                 linkedIssuesPrs.add(`${link.subject.number}`);
213.               }
214.               seen.add(link.subject.number);
215.             }
216.           }
217.         })()
218.       )
219.     );
220. 
221.     const requests: Array<Promise<unknown>> = [];
222.     for (const issueStr of linkedIssuesPrs) {
223.       const issueNumber = parseInt(issueStr);
224.       const baseRequest = {
225.         ...github.context.repo,
226.         issue_number: issueNumber,
227.       };
228.       if (comment) {
229.         const request = {
230.           ...baseRequest,
231.           body: comment,
232.         };
233.         core.info(JSON.stringify(request, null, 2));
234.         requests.push(octokit.issues.createComment(request));
235.       }
236.       if (labels) {
237.         const request = {
238.           ...baseRequest,
239.           labels,
240.         };
241.         core.info(JSON.stringify(request, null, 2));
242.         requests.push(octokit.issues.addLabels(request));
243.       }
244.     }
245.     await Promise.all(requests);
246.   } catch (error) {
247.     core.error(error);
248.     core.setFailed(error.message);
249.   }
250. })();
251.

